import { signLicense, verifyLicense, ecdsaDerToRaw } from "@sweberdev/integral";
import { generateKeyPairSync, sign } from "node:crypto";

const { privateKey } = generateKeyPairSync("ec", { namedCurve: "P-256" });
const kmsSignSha256 = async (data) => sign("sha256", data, privateKey);

const signer = {
  alg: "ES256",
  kid: "kms-2027",
  sign: async (data) => ecdsaDerToRaw(await kmsSignSha256(data)),
};
const license = await signLicense({ product: "app", plan: "pro" }, signer);
